def transform(g):
    h=len(g); w=len(g[0])
    out=[[0]*w for _ in range(h)]
    def put(cells):
        for r,c,v in cells:
            if 0<=r<h and 0<=c<w: out[r][c]=v
    shapes={'1':[],'2':[],'3':[],'6':[]}
    anchors={}
    for r in range(h):
        for c in range(w):
            v=g[r][c]
            if v: anchors.setdefault(v,(r,c))
    def line(cells): return cells
    # draw 5-filled shapes first, then endpoints, then 4-diagonal last
    fills=[]; ends=[]; diag=[]
    for v,(r,c) in anchors.items():
        if v==1:
            fills+= [(r,c+1,5),(r,c+2,5)]; ends+=[(r,c,1),(r-1,c+2,1)]
        elif v==2:
            for i in range(1,4): fills.append((r,c-i,5))
            ends+=[(r,c,2),(r,c-4,2)]
        elif v==3:
            for i in (1,2): fills.append((r+i,c,5))
            ends+=[(r,c,3),(r+3,c,3)]
        elif v==4:
            for i in range(5): diag.append((r+i,c-i,4))
        elif v==6:
            for i in range(1,6): fills.append((r-i,c,5))
            ends+=[(r,c,6),(r-6,c,6)]
    for lst in (fills,ends,diag):
        put(lst)
    return out

